import{_ as r,C as o,o as i,c as d,j as t,a,E as n,ag as l}from"./chunks/framework.DMVuHR7L.js";const y=JSON.parse('{"title":"Simulated stream","description":"","frontmatter":{},"headers":[],"relativePath":"features/simulator.md","filePath":"features/simulator.md","lastUpdated":1778529672000}'),c={name:"features/simulator.md"};function h(m,e,u,p,g,f){const s=o("ThemeImage");return i(),d("div",null,[e[0]||(e[0]=t("h1",{id:"simulated-stream",tabindex:"-1"},[a("Simulated stream "),t("a",{class:"header-anchor",href:"#simulated-stream","aria-label":'Permalink to "Simulated stream"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("Click "),t("strong",null,"fake data"),a(" on the empty state to swap a real device for an in-memory simulator. Every widget keeps working — Logcat replays a synthetic event stream, Shell answers a few common commands from a host-side fake, Dumpsys serves canned output, Files browses an in-memory tree, and Mirror renders a static device home screen.")],-1)),n(s,{"src-dark":"/img/features/simulator-empty.png","src-light":"/img/features/simulator-empty-light.png",alt:"Simulator landing"}),e[2]||(e[2]=l('<h2 id="why-use-it" tabindex="-1">Why use it <a class="header-anchor" href="#why-use-it" aria-label="Permalink to &quot;Why use it&quot;">​</a></h2><ul><li><strong>Try the app without a phone.</strong> Useful for evaluating the dashboard, sharing screenshots, or designing a layout you&#39;ll use later on real hardware.</li><li><strong>Demo / docs.</strong> Every screenshot in this site is captured against the simulator (with the exception of real-device-only flows, which are flagged).</li><li><strong>Tests.</strong> WebLogcat&#39;s e2e suite drives every widget through the simulator path because real WebUSB cannot be exercised in headless CI. See <a href="./../bots/test-sync">test-sync rules</a> for the contract.</li></ul><h2 id="what-s-faked" tabindex="-1">What&#39;s faked <a class="header-anchor" href="#what-s-faked" aria-label="Permalink to &quot;What&#39;s faked&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Widget</th><th>Source</th></tr></thead><tbody><tr><td>Logcat</td><td><code>lib/logGenerator.ts</code> — synthesises ~5–20 entries / sec across realistic packages and tags.</td></tr><tr><td>Shell</td><td><code>lib/shellSim.ts</code> — recognises a small set of built-ins (<code>pwd</code>, <code>ls</code>, <code>cat</code>, <code>whoami</code>, etc.) and a tiny in-memory FS under <code>/sdcard/</code>.</td></tr><tr><td>Dumpsys</td><td>Captured fixtures for each preset, parsed by the same code path the real output uses.</td></tr><tr><td>Files</td><td>An in-memory tree rooted at <code>/sdcard/</code> with a few canned files.</td></tr><tr><td>Mirror</td><td>A static <code>mirror-home.png</code> framed inside the bezel chrome.</td></tr></tbody></table><p>The badge in the lower-right corner of the dashboard reminds you that you&#39;re on simulated data. Switching back to a real device is one click in the device picker.</p><h2 id="stream-speed" tabindex="-1">Stream speed <a class="header-anchor" href="#stream-speed" aria-label="Permalink to &quot;Stream speed&quot;">​</a></h2><p>The simulator emits log entries at a configurable rate. Open the global settings cog and adjust <strong>Simulated stream speed</strong> between <em>trickle</em> (~1/s) and <em>firehose</em> (~50/s) — useful for stress-testing the Logcat widget.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><p>The simulator is intentionally shallow — it&#39;s a stand-in for &quot;the app works&quot;, not a faithful Android emulator. Expect:</p><ul><li>No real <code>adb</code> semantics: the shell built-ins don&#39;t cover the full toolbox; <code>find</code>, <code>grep</code>, and friends aren&#39;t there.</li><li>No real Mirror feed: the canvas shows a static image so the widget chrome can be inspected.</li><li>No real Files transfers: drag-out / drag-in are no-ops in the simulator.</li></ul><p>For the real flows, pair an Android device — see <a href="./connecting">connecting</a>.</p>',11))])}const w=r(c,[["render",h]]);export{y as __pageData,w as default};
